  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Bromfenac, a structurally related benzoyl arylacetic acid NSAID, showed 67% absolute oral bioavailability in fasting healthy subjects, directly supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Ampicillin, a zwitterionic carboxylic acid with ionization and permeability challenges, had absolute oral bioavailability of about 55%, supporting that carboxylic-acid-containing drugs can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Tranexamic acid, a small zwitterionic carboxylic acid, showed 33.4% systemic bioavailability under fasting conditions, demonstrating that highly ionized carboxylic acids can still achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Ketanserin, a ketone-containing drug with moderate lipophilicity, had absolute oral bioavailability of 55.5% in healthy subjects, supporting high F for the query's structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Thalidomide, a moderately polar heterocyclic drug, showed probably high oral bioavailability of 80–100% in fasting healthy volunteers, reinforcing that the query's features are compatible with high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, including structurally related carboxylic acids and ketone-containing drugs, show absolute oral bioavailability values well above the 20% threshold under fasting conditions. The physicochemical prior of poor passive absorption is outweighed by consistent experimental evidence that such ionized carboxylic acids can be efficiently absorbed, so the query is predicted to have high oral bioavailability.",
